const query = $('Petition List Webhook').first().json.query || {};
const category = String(query.category || '').trim();
const status = String(query.status || '').trim();
const page = Math.max(parseInt(query.page || '1', 10) || 1, 1);
const pageSize = Math.min(Math.max(parseInt(query.pageSize || '15', 10) || 15, 1), 50);
const offset = (page - 1) * pageSize;
const typeList = ['醫療院所','市府單位','法律諮詢','一般請託','學籍安排','法律服務','府外單位','車禍','人事案','違章建築'];
function getString(prop) {
  if (!prop) return '';
  if (prop.type === 'title') return (prop.title || []).map(t => t.plain_text || '').join('');
  if (prop.type === 'rich_text') return (prop.rich_text || []).map(t => t.plain_text || '').join('');
  if (prop.type === 'select') return prop.select?.name || '';
  if (prop.type === 'multi_select') return (prop.multi_select || []).map(t => t.name || '').filter(Boolean).join('、');
  if (prop.type === 'checkbox') return prop.checkbox === true ? 'true' : 'false';
  if (prop.type === 'date') return prop.date?.start || '';
  if (prop.type === 'created_time') return prop.created_time || '';
  if (prop.type === 'last_edited_time') return prop.last_edited_time || '';
  if (prop.type === 'phone_number') return prop.phone_number || '';
  if (prop.type === 'number') return prop.number == null ? '' : String(prop.number);
  return '';
}
function getImages(prop) {
  if (!prop || prop.type !== 'files') return [];
  return (prop.files || []).map(f => f.file?.url || f.external?.url || '').filter(Boolean);
}
let items = $input.all().map(item => {
  const props = item.json.properties || {};
  const summary = getString(props['公開摘要']);
  const content = getString(props['託辦事項']);
  return {
    id: item.json.id,
    caseId: getString(props['請託案號']),
    caseType: getString(props['託辦類別']),
    caseArea: getString(props['案件區域']),
    title: summary || content,
    status: getString(props['處理狀況']),
    summary,
    reply: getString(props['回覆內容']),
    beforeImages: getImages(props['改善前圖片']),
    afterImages: getImages(props['改善後圖片']),
    date: (getString(props['請託日期']) || getString(props['建立時間'])).slice(0, 10),
    lastUpdate: getString(props['上次編輯時間']).slice(0, 10),
    isPublic: getString(props['是否公開']) === 'true'
  };
}).filter(item => item.isPublic);
const categories = Object.fromEntries(typeList.map(type => [type, 0]));
items.forEach(item => { if (categories[item.caseType] !== undefined) categories[item.caseType] += 1; });
if (category) items = items.filter(item => item.caseType === category);
if (status) items = items.filter(item => item.status === status);
items.sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')) || String(b.lastUpdate || '').localeCompare(String(a.lastUpdate || '')));
const total = items.length;
const paged = items.slice(offset, offset + pageSize);
return [{ json: { success: true, total, page, pageSize, totalPages: Math.max(Math.ceil(total / pageSize), 1), categories, items: paged } }];
